    },
    {
      "name": "TEST",
      "entry": "Pallet in ST30 (X33) AND guard door closed (X32) AND E-stop healthy (X0) AND no result latched (M310/M311 clear)",
      "exit": "Tester PASS received (X30) OR tester FAIL received (X31) OR guard door opened (X32 lost) OR E-stop tripped (X0 lost)"
    },
    {
      "name": "RESULT",
      "entry": "Tester PASS (X30 sets M310) OR tester FAIL (X31 sets M311)",
      "exit": "Pallet leaves ST30 (falling edge of X33)"
    }
  ],
  "interlocks": [
    {
      "cause": "Guard door opened (ZS-3002 / X32 lost) or E-stop chain lost (ES-0001 / X0 lost)",
      "effect": "HV enable (HP-3005 / Y30) and HV beacon (HL-3006 / Y31) removed immediately"
    },
    {
      "cause": "HiPot result latched (PASS M310 or FAIL M311 set)",
      "effect": "HV enable (HP-3005 / Y30) and HV beacon (HL-3006 / Y31) disabled"
    },
    {
      "cause": "Pallet leaves ST30 (ZS-3001 / X33 falling edge)",
      "effect": "Reset latched PASS (M310) and FAIL (M311) results"
    }
  ],
